//! Owned derivative cache directory: confinement, path construction, and
//! bounded derivative admission.
//!
//! The directory is deliberately separate from [`crate::confinement::LibraryRoot`].
//! It owns generated bytes, while Originals remain read-only capabilities held
//! by the caller. All generated names are fixed hexadecimal names or private
//! temporary names, so identities never become paths.

use super::cache_metadata::{
    DerivativeProfileWire, Manifest, ManifestFacts, manifest_key_is_valid, read_manifest,
};
use super::{
    CACHE_NAMESPACE, CacheError, CachedDerivative, DerivativeIdentity, DerivativeSource,
    DerivativeTarget, MAXIMUM_OUTPUT_BYTES, is_hex_key, manifest_identity_for_photo_target,
};
use crate::{
    OriginalRecord, PhotoRecord, PreviewSource,
    derivative::{Derivative, DerivativeError, DerivativeProfile},
    source_revision,
};
use image::{ImageDecoder, codecs::jpeg::JpegDecoder};
use lcms2::Profile;
use std::{
    fs::{self, OpenOptions},
    io::{Cursor, Read},
    path::{Component, Path, PathBuf},
    sync::Arc,
};

#[cfg(unix)]
use std::os::unix::fs::OpenOptionsExt;

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CacheDirectory {
    root: Arc<CacheDirectoryInner>,
}

#[derive(Debug, Eq, PartialEq)]
struct CacheDirectoryInner {
    canonical_root: PathBuf,
    namespace_root: PathBuf,
    canonical_original_root: PathBuf,
}

impl CacheDirectory {
    /// Opens an owned cache directory and rejects a cache located below Originals.
    ///
    /// The canonical path is retained after this check. All generated names are fixed
    /// hexadecimal names or private temporary names, so identities never become paths.
    pub fn open(
        cache_directory: impl AsRef<Path>,
        original_root: impl AsRef<Path>,
    ) -> Result<Self, CacheError> {
        let cache_directory = cache_directory.as_ref();
        let original_root = original_root.as_ref();
        if !cache_directory.is_absolute() || !original_root.is_absolute() {
            return Err(CacheError::InvalidCacheDirectory);
        }
        if cache_directory.to_str().is_none() || original_root.to_str().is_none() {
            return Err(CacheError::UnsupportedEncoding);
        }
        let canonical_original_root =
            fs::canonicalize(original_root).map_err(|_| CacheError::InvalidCacheDirectory)?;
        if !canonical_original_root.is_dir() {
            return Err(CacheError::InvalidCacheDirectory);
        }
        reject_cache_under_original(cache_directory, &canonical_original_root)?;
        fs::create_dir_all(cache_directory).map_err(|_| CacheError::Io)?;
        let canonical_root = fs::canonicalize(cache_directory).map_err(|_| CacheError::Io)?;
        if !canonical_root.is_dir()
            || canonical_root == canonical_original_root
            || canonical_root.starts_with(&canonical_original_root)
        {
            return Err(CacheError::InvalidCacheDirectory);
        }
        if canonical_root.to_str().is_none() {
            return Err(CacheError::UnsupportedEncoding);
        }
        let namespace_path = canonical_root.join(CACHE_NAMESPACE);
        fs::create_dir_all(&namespace_path).map_err(|_| CacheError::Io)?;
        let namespace_root = fs::canonicalize(&namespace_path).map_err(|_| CacheError::Io)?;
        if !namespace_root.is_dir()
            || !namespace_root.starts_with(&canonical_root)
            || namespace_root.to_str().is_none()
        {
            return Err(CacheError::InvalidCacheDirectory);
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut permissions = fs::metadata(&canonical_root)
                .map_err(|_| CacheError::Io)?
                .permissions();
            permissions.set_mode(0o700);
            fs::set_permissions(&canonical_root, permissions).map_err(|_| CacheError::Io)?;
        }
        Ok(Self {
            root: Arc::new(CacheDirectoryInner {
                canonical_root,
                namespace_root,
                canonical_original_root,
            }),
        })
    }

    pub fn root(&self) -> &Path {
        &self.root.canonical_root
    }

    pub fn original_root(&self) -> &Path {
        &self.root.canonical_original_root
    }

    /// Looks up one current derivative from persisted cache metadata and the
    /// Library's published source facts. This path never opens an Original.
    /// Missing or invalid cache state is a miss so callers can use the normal
    /// bounded source-inspection path.
    pub fn lookup_current(
        &self,
        photo: &PhotoRecord,
        originals: &[OriginalRecord],
        target: DerivativeTarget,
    ) -> Result<Option<CachedDerivative>, CacheError> {
        let Some(manifest) = self.current_manifest(photo, originals, target)? else {
            return Ok(None);
        };
        let Some(facts) = inspect_cached(&self.derivative_path(&manifest.key), target, &manifest)
        else {
            return Ok(None);
        };
        Ok(Some(cached_from_manifest(self, &manifest, facts, false)))
    }

    /// Returns the current manifest key after bounded metadata checks. This is
    /// only for Browse Window URL hydration; Preview requests and derivative
    /// delivery perform complete JPEG validation before serving bytes.
    pub fn lookup_current_key(
        &self,
        photo: &PhotoRecord,
        originals: &[OriginalRecord],
        target: DerivativeTarget,
    ) -> Result<Option<String>, CacheError> {
        Ok(self
            .current_manifest(photo, originals, target)?
            .map(|manifest| manifest.key))
    }

    fn current_manifest(
        &self,
        photo: &PhotoRecord,
        originals: &[OriginalRecord],
        target: DerivativeTarget,
    ) -> Result<Option<Manifest>, CacheError> {
        let path = self.manifest_path_for_photo_target(&photo.id, target)?;
        let Ok(manifest) = read_manifest(&path) else {
            return Ok(None);
        };
        let Some((source, original)) = selected_original(photo, originals) else {
            return Ok(None);
        };

        let manifest_source = match source {
            PreviewSource::JpegOriginal => DerivativeSource::MatchingJpeg,
            PreviewSource::RawEmbeddedJpeg => DerivativeSource::EmbeddedRawJpeg,
        };
        if !manifest_key_is_valid(&manifest)
            || manifest.photo_identity != photo.id
            || manifest.target_long_edge != target.long_edge()
            || manifest.source != manifest_source
            || manifest.source_relative_path != original.relative_path.as_str()
            || manifest.source_size != original.facts.size
            || manifest.source_mtime_ms != original.facts.mtime_ms
            || (source == PreviewSource::JpegOriginal
                && manifest.embedded_candidate_identity.is_some())
            || photo
                .preview_source_revision
                .as_deref()
                .is_some_and(|stored| {
                    stored
                        != source_revision(
                            original.relative_path.as_str(),
                            original.facts.size,
                            original.facts.mtime_ms,
                        )
                        .ok()
                        .as_deref()
                        .unwrap_or("")
                })
        {
            return Ok(None);
        }
        let metadata = fs::symlink_metadata(self.derivative_path(&manifest.key)).ok();
        if !metadata.is_some_and(|metadata| {
            metadata.is_file() && metadata.len() > 0 && metadata.len() <= MAXIMUM_OUTPUT_BYTES
        }) {
            return Ok(None);
        }
        Ok(Some(manifest))
    }

    fn manifest_path_for_photo_target(
        &self,
        photo_id: &str,
        target: DerivativeTarget,
    ) -> Result<PathBuf, CacheError> {
        let identity = manifest_identity_for_photo_target(photo_id, target)?;
        Ok(self
            .root
            .namespace_root
            .join("metadata")
            .join("manifests")
            .join(format!("{identity}.json")))
    }

    /// Reads one already-published derivative by its cache identity.
    ///
    /// Callers provide only the validated hexadecimal identity; cache path
    /// construction and no-follow file admission remain inside the cache
    /// boundary. This keeps filesystem paths out of the HTTP and Preview APIs.
    pub fn read_derivative(
        &self,
        key: &str,
        target: DerivativeTarget,
    ) -> Result<Vec<u8>, CacheError> {
        if !is_hex_key(key) {
            return Err(CacheError::InvalidIdentity);
        }
        let path = self.derivative_path(key);
        let file = OpenOptions::new()
            .read(true)
            .custom_flags(no_follow_flag())
            .open(path)
            .map_err(|_| CacheError::Io)?;
        let metadata = file.metadata().map_err(|_| CacheError::Io)?;
        if !metadata.is_file() || metadata.len() == 0 || metadata.len() > MAXIMUM_OUTPUT_BYTES {
            return Err(CacheError::InvalidCachedDerivative);
        }
        let mut bytes = Vec::with_capacity(metadata.len() as usize);
        file.take(MAXIMUM_OUTPUT_BYTES + 1)
            .read_to_end(&mut bytes)
            .map_err(|_| CacheError::Io)?;
        if bytes.len() as u64 > MAXIMUM_OUTPUT_BYTES {
            return Err(CacheError::InvalidCachedDerivative);
        }
        let Some(facts) = jpeg_facts(&bytes) else {
            return Err(CacheError::InvalidCachedDerivative);
        };
        if facts.width.max(facts.height) > target.long_edge()
            || validate_jpeg_bytes(&bytes, facts, false).is_none()
        {
            return Err(CacheError::InvalidCachedDerivative);
        }
        Ok(bytes)
    }

    pub(super) fn derivative_path(&self, key: &str) -> PathBuf {
        self.root.namespace_root.join(format!("{key}.jpg"))
    }

    pub(super) fn manifest_path(
        &self,
        identity: &DerivativeIdentity,
    ) -> Result<PathBuf, CacheError> {
        self.manifest_path_for_photo_target(&identity.photo_identity, identity.target)
    }

    pub(super) fn failure_path(&self, key: &str) -> PathBuf {
        self.root
            .namespace_root
            .join("metadata")
            .join("failures")
            .join(format!("{key}.json"))
    }

    pub(super) fn ensure_metadata(&self) -> Result<(), CacheError> {
        fs::create_dir_all(self.root.namespace_root.join("metadata/manifests"))
            .map_err(|_| CacheError::Io)?;
        fs::create_dir_all(self.root.namespace_root.join("metadata/failures"))
            .map_err(|_| CacheError::Io)?;
        Ok(())
    }
}

pub(super) fn selected_original<'a>(
    photo: &PhotoRecord,
    originals: &'a [OriginalRecord],
) -> Option<(PreviewSource, &'a OriginalRecord)> {
    originals.iter().find_map(|original| {
        (original.id == photo.original_id
            && original.available
            && original.error_category.is_none())
        .then_some((original.kind.preview_source(), original))
    })
}

pub(super) fn inspect_cached(
    path: &Path,
    target: DerivativeTarget,
    manifest: &Manifest,
) -> Option<ManifestFacts> {
    let metadata = fs::symlink_metadata(path).ok()?;
    if !metadata.is_file() || metadata.len() == 0 || metadata.len() > MAXIMUM_OUTPUT_BYTES {
        return None;
    }
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(no_follow_flag())
        .open(path)
        .ok()?;
    let mut bytes = Vec::with_capacity(metadata.len() as usize);
    file.take(MAXIMUM_OUTPUT_BYTES + 1)
        .read_to_end(&mut bytes)
        .ok()?;
    if bytes.len() as u64 > MAXIMUM_OUTPUT_BYTES {
        return None;
    }
    let facts = jpeg_facts(&bytes)?;
    if facts.width != manifest.width
        || facts.height != manifest.height
        || facts.width.max(facts.height) > target.long_edge()
    {
        return None;
    }
    validate_cached_jpeg(&bytes, facts, manifest.color_profile)?;
    Some(facts)
}

pub(super) fn validate_processed(
    processed: &Derivative,
    target: DerivativeTarget,
) -> Result<(), DerivativeError> {
    if processed.jpeg.is_empty() || processed.jpeg.len() as u64 > MAXIMUM_OUTPUT_BYTES {
        return Err(DerivativeError::OutputLimit);
    }
    if processed.width == 0
        || processed.height == 0
        || processed.width.max(processed.height) > target.long_edge()
    {
        return Err(DerivativeError::Internal);
    }
    let facts = jpeg_facts(&processed.jpeg).ok_or(DerivativeError::Malformed)?;
    if facts.width != processed.width || facts.height != processed.height {
        return Err(DerivativeError::Internal);
    }
    if processed.profile == DerivativeProfile::PreservedIcc && !contains_icc(&processed.jpeg) {
        return Err(DerivativeError::Internal);
    }
    Ok(())
}

pub(super) fn jpeg_facts(bytes: &[u8]) -> Option<ManifestFacts> {
    if bytes.len() < 4 || bytes[0] != 0xff || bytes[1] != 0xd8 {
        return None;
    }
    let mut offset = 2usize;
    let mut dimensions = None;
    let mut saw_scan = false;
    let mut saw_eoi = false;
    while offset + 1 < bytes.len() {
        while offset < bytes.len() && bytes[offset] == 0xff {
            offset += 1;
        }
        if offset >= bytes.len() {
            break;
        }
        let marker = bytes[offset];
        offset += 1;
        if marker == 0xd9 {
            saw_eoi = true;
            break;
        }
        if marker == 0xda {
            saw_scan = true;
            break;
        }
        if marker == 0x00 || (0xd0..=0xd7).contains(&marker) {
            continue;
        }
        if offset + 2 > bytes.len() {
            return None;
        }
        let length = u16::from_be_bytes([bytes[offset], bytes[offset + 1]]) as usize;
        if length < 2 || offset + length > bytes.len() {
            return None;
        }
        if is_jpeg_frame_marker(marker) {
            if length < 7 {
                return None;
            }
            let height = u16::from_be_bytes([bytes[offset + 3], bytes[offset + 4]]) as u32;
            let width = u16::from_be_bytes([bytes[offset + 5], bytes[offset + 6]]) as u32;
            if width == 0 || height == 0 {
                return None;
            }
            dimensions = Some(ManifestFacts { width, height });
        }
        offset += length;
    }
    if saw_scan {
        let mut index = offset;
        while index + 1 < bytes.len() {
            if bytes[index] == 0xff && bytes[index + 1] == 0xd9 {
                saw_eoi = true;
                break;
            }
            index += 1;
        }
    }
    if !saw_eoi && bytes.ends_with(&[0xff, 0xd9]) {
        saw_eoi = true;
    }
    dimensions.filter(|_| saw_eoi)
}

const fn is_jpeg_frame_marker(marker: u8) -> bool {
    matches!(marker, 0xc0..=0xc3 | 0xc5..=0xc7 | 0xc9..=0xcb | 0xcd..=0xcf)
}

pub(super) fn validate_cached_jpeg(
    bytes: &[u8],
    facts: ManifestFacts,
    profile: DerivativeProfileWire,
) -> Option<()> {
    validate_jpeg_bytes(bytes, facts, profile == DerivativeProfileWire::PreservedIcc)
}

fn validate_jpeg_bytes(bytes: &[u8], facts: ManifestFacts, require_icc: bool) -> Option<()> {
    let mut decoder = JpegDecoder::new(Cursor::new(bytes)).ok()?;
    if decoder.dimensions() != (facts.width, facts.height) {
        return None;
    }
    let icc = decoder.icc_profile().ok().flatten();
    if require_icc && icc.is_none() {
        return None;
    }
    if let Some(icc) = icc {
        Profile::new_icc(&icc).ok()?;
    }
    let decoded_bytes = usize::try_from(decoder.total_bytes()).ok()?;
    let mut decoded = vec![0; decoded_bytes];
    decoder.read_image(&mut decoded).ok()?;
    Some(())
}

fn contains_icc(bytes: &[u8]) -> bool {
    bytes.windows(12).any(|window| window == b"ICC_PROFILE\0")
}

pub(super) fn cached_from_manifest(
    cache: &CacheDirectory,
    manifest: &Manifest,
    facts: ManifestFacts,
    generated: bool,
) -> CachedDerivative {
    CachedDerivative {
        cache_path: cache.derivative_path(&manifest.key),
        cache_key: manifest.key.clone(),
        source: manifest.source,
        source_relative_path: manifest.source_relative_path.clone(),
        source_size: manifest.source_size,
        source_mtime_ms: manifest.source_mtime_ms,
        embedded_candidate_identity: manifest.embedded_candidate_identity.clone(),
        width: facts.width,
        height: facts.height,
        profile: manifest.color_profile.into(),
        generated,
        stale: false,
    }
}

fn reject_cache_under_original(
    cache_directory: &Path,
    canonical_original_root: &Path,
) -> Result<(), CacheError> {
    let lexical_cache = lexical_absolute_path(cache_directory)?;
    if lexical_cache == canonical_original_root
        || lexical_cache.starts_with(canonical_original_root)
    {
        return Err(CacheError::InvalidCacheDirectory);
    }
    let mut existing = cache_directory;
    while !existing.exists() {
        existing = existing.parent().ok_or(CacheError::InvalidCacheDirectory)?;
    }
    let canonical_existing =
        fs::canonicalize(existing).map_err(|_| CacheError::InvalidCacheDirectory)?;
    if canonical_existing == canonical_original_root
        || canonical_existing.starts_with(canonical_original_root)
    {
        return Err(CacheError::InvalidCacheDirectory);
    }
    Ok(())
}

fn lexical_absolute_path(path: &Path) -> Result<PathBuf, CacheError> {
    let mut result = PathBuf::new();
    for component in path.components() {
        match component {
            Component::RootDir => result.push(component.as_os_str()),
            Component::Normal(value) => result.push(value),
            Component::CurDir => {}
            Component::ParentDir => {
                result.pop();
            }
            Component::Prefix(_) => return Err(CacheError::InvalidCacheDirectory),
        }
    }
    Ok(result)
}

pub(super) fn is_safe_relative_utf8_path(value: &str) -> bool {
    let path = Path::new(value);
    if value.is_empty() || path.is_absolute() {
        return false;
    }
    path.components()
        .all(|component| matches!(component, Component::Normal(_)))
}

#[cfg(unix)]
pub(super) const fn no_follow_flag() -> i32 {
    libc::O_NOFOLLOW | libc::O_CLOEXEC
}

#[cfg(not(unix))]
pub(super) const fn no_follow_flag() -> i32 {
    0
}
